# illustrative (NOT in repo): per-connection token bucket for ops
class Bucket:
    def __init__(self, rate=20, burst=40):
        self.rate, self.tokens, self.burst, self.t = rate, burst, burst, time.monotonic()
    def take(self) -> bool:
        now = time.monotonic()
        self.tokens = min(self.burst, self.tokens + (now - self.t) * self.rate); self.t = now
        if self.tokens >= 1:
            self.tokens -= 1; return True
        return False

